files.analyses/audit_fct_monthly_revenue.sql:
{#
    Compare the refactored fct_monthly_revenue with the legacy SQL of Chapter 9,
    using the audit_helper package. Run it with:
        dbt show --select audit_fct_monthly_revenue
#}

{% set legacy_query %}
SELECT DATE_TRUNC('month', X.ORDER_DATE) AS ORDER_MONTH, C.COUNTRY,
COUNT(*) AS NUMBER_OF_ORDERS, SUM(X.PAID_CENTS) / 100 AS REVENUE
FROM (SELECT O.ID, O.USER_ID, O.ORDER_DATE,
        COALESCE((SELECT SUM(P.AMOUNT) FROM PRACTICE.STRIPE.PAYMENTS P
                  WHERE P.ORDERID = O.ID AND P.STATUS = 'success'), 0) AS PAID_CENTS
      FROM PRACTICE.JAFFLE_SHOP.ORDERS O
      WHERE O.STATUS NOT IN ('returned', 'return_pending')) X
LEFT JOIN (SELECT ID, COUNTRY FROM PRACTICE.JAFFLE_SHOP.CUSTOMERS) C ON C.ID = X.USER_ID
GROUP BY 1, 2
{% endset %}

{% set refactored_query %}
select order_month, country, number_of_orders, revenue
from {{ ref('fct_monthly_revenue') }}
{% endset %}

{{ audit_helper.compare_queries(
    a_query=legacy_query,
    b_query=refactored_query,
    summarize=true
) }}

files.macros/cents_to_dollars.sql:
{#
    Convert an integer amount in cents into dollars, as an exact decimal.
    Example: {{ cents_to_dollars('amount') }}  ->  cast(amount / 100 as decimal(16, 2))
#}
{% macro cents_to_dollars(column_name, scale=2) -%}
    cast({{ column_name }} / 100 as decimal(16, {{ scale }}))
{%- endmacro %}

files.macros/generate_schema_name.sql:
{#
    Common dev/prod pattern:
    - prod target: use the custom schema as it is (marts -> marts),
      or the target schema when the model has no custom schema (-> prod)
    - any other target (dev, ci...): everything goes to the target schema
      (dbt_adnane), so each developer keeps one personal schema
#}
{% macro generate_schema_name(custom_schema_name, node) -%}

    {%- set default_schema = target.schema -%}

    {%- if target.name == 'prod' and custom_schema_name is not none -%}

        {{ custom_schema_name | trim }}

    {%- else -%}

        {{ default_schema }}

    {%- endif -%}

{%- endmacro %}

files.macros/print_row_counts.sql:
{#
    Print the number of rows of every model built as one of the given
    materializations. Run it with:
        dbt run-operation print_row_counts
        dbt run-operation print_row_counts --args '{materializations: [view]}'
#}
{% macro print_row_counts(materializations=['table', 'incremental']) %}

    {% if execute %}
        {% for node in graph.nodes.values()
              | selectattr('resource_type', 'equalto', 'model')
              | sort(attribute='name') %}
            {% if node.config.materialized in materializations %}
                {% set relation = adapter.get_relation(
                    database=node.database,
                    schema=node.schema,
                    identifier=node.alias) %}
                {% if relation is none %}
                    {{ log(node.name ~ ': not built yet', info=true) }}
                {% else %}
                    {% set result = run_query('select count(*) from ' ~ relation) %}
                    {{ log(node.name ~ ': ' ~ result.columns[0].values()[0] ~ ' rows', info=true) }}
                {% endif %}
            {% endif %}
        {% endfor %}
    {% endif %}

{% endmacro %}

files.models/intermediate/int_orders__payment_:
{%- set payment_methods = ['bank_transfer', 'coupon', 'credit_card', 'gift_card'] -%}

with

payments as (

    select * from {{ ref('int_payments__successful') }}

),

pivoted as (

    select
        order_id,
        {% for payment_method in payment_methods -%}
        sum(case when payment_method = '{{ payment_method }}' then amount else 0 end)
            as {{ payment_method }}_amount
        {%- if not loop.last %},{% endif %}
        {% endfor %}
    from payments
    group by order_id

)

select * from pivoted
